function distance(fromDir, toDir) {
  const a = fromDir === '.' ? [] : fromDir.split('/');
  const b = toDir === '.' ? [] : toDir.split('/');
  let common = 0;
  while (common < a.length && common < b.length && a[common] === b[common]) common += 1;
  return (a.length - common) + (b.length - common);
}

